import { expectStatus, test } from "../../fixtures";

test("Audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that belongs to another tenant (Globex Procurement).
  const otherTenantVendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act: the Northwind member requests that vendor's audit trail.
  const response = await member.get(`/api/vendors/${otherTenantVendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
